export function encodeCsvField(value) {
  if (typeof value !== 'string') {
    throw new TypeError();
  }
  if (
    value === '' ||
    value.includes(',') ||
    value.includes('"') ||
    value.includes('\r') ||
    value.includes('\n')
  ) {
    return `"${value.replaceAll('"', '""')}"`;
  }
  return value;
}

