import { encodeCsvField } from './csv-field.mjs';

export function parseCsv(text) {
  if (typeof text !== 'string') {
    throw new TypeError();
  }
  if (text === '') {
    return [];
  }

  const rows = [];
  let row = [];
  let field = '';
  let i = 0;
  let inQuotes = false;

  while (i < text.length) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        inQuotes = false;
        i += 1;
        if (i >= text.length) {
          row.push(field);
          rows.push(row);
          row = [];
          field = '';
          break;
        }
        const next = text[i];
        if (next === ',') {
          row.push(field);
          field = '';
          i += 1;
        } else if (next === '\r') {
          row.push(field);
          field = '';
          if (text[i + 1] === '\n') {
            i += 2;
          } else {
            i += 1;
          }
          rows.push(row);
          row = [];
        } else if (next === '\n') {
          row.push(field);
          field = '';
          i += 1;
          rows.push(row);
          row = [];
        } else {
          throw new SyntaxError();
        }
      } else {
        field += c;
        i += 1;
      }
      continue;
    }

    if (c === '"') {
      if (field.length > 0) {
        throw new SyntaxError();
      }
      inQuotes = true;
      i += 1;
    } else if (c === ',') {
      row.push(field);
      field = '';
      i += 1;
    } else if (c === '\r') {
      row.push(field);
      field = '';
      if (text[i + 1] === '\n') {
        i += 2;
      } else {
        i += 1;
      }
      rows.push(row);
      row = [];
    } else if (c === '\n') {
      row.push(field);
      field = '';
      i += 1;
      rows.push(row);
      row = [];
    } else {
      field += c;
      i += 1;
    }
  }

  if (inQuotes) {
    throw new SyntaxError();
  }

  if (field !== '' || row.length > 0) {
    row.push(field);
    rows.push(row);
  }

  return rows;
}

export function serializeCsv(rows) {
  if (!Array.isArray(rows)) {
    throw new TypeError();
  }
  if (rows.length === 0) {
    return '';
  }
  const lines = [];
  for (const row of rows) {
    if (!Array.isArray(row) || row.length === 0) {
      throw new TypeError();
    }
    const encoded = row.map((field) => {
      if (typeof field !== 'string') {
        throw new TypeError();
      }
      return encodeCsvField(field);
    });
    lines.push(encoded.join(','));
  }
  return lines.join('\r\n');
}

